import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"NanoGPT (BYOK Provider)","description":"","frontmatter":{"title":"NanoGPT (BYOK Provider)"},"headers":[],"relativePath":"providers/nanogpt.md","filePath":"providers/nanogpt.md"}`),a={name:`providers/nanogpt.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="nanogpt-mode-byok" tabindex="-1">NanoGPT (Mode BYOK) <a class="header-anchor" href="#nanogpt-mode-byok" aria-label="Permalink to “NanoGPT (Mode BYOK)”">​</a></h1><p><strong>NanoGPT</strong> adalah &quot;private pay-per-use AI&quot; dengan <strong>1.000+ model</strong> dalam satu tempat — teks (ChatGPT, Claude, Gemini, GLM), gambar, video (184+), dan audio — semuanya dibayar lewat <strong>satu saldo prepaid</strong>. Yang membuatnya beda dari semua provider lain di panduan ini: NanoGPT sangat <strong>ramah anonimitas</strong> — harga dijual <em>list price</em> tanpa markup, dan API-nya bahkan bisa dipakai <strong>tanpa membuat akun</strong> (cukup deposit kecil). Tidak heran komunitas SillyTavern menyukainya: privasi ramah, pembayaran crypto mudah, dan akses langsung ke banyak model sekaligus. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Harga per model, daftar model, dan fitur NanoGPT cukup dinamis — <strong>Private Mode &amp; PII redaction</strong> baru diluncurkan Mei 2026, dan katalognya terus bertambah. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan daftar angka. Cek halaman resmi <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">nano-gpt.com/api</a> dan <a href="https://nano-gpt.com/get-started" target="_blank" rel="noreferrer">get-started</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Buka <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">nano-gpt.com/api</a>.</li><li>Klik <strong>Create a key</strong>.</li><li>Salin key yang ditampilkan — key ini nanti dikirim sebagai header <code>Authorization: Bearer</code> atau <code>x-api-key</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">🔐 Ada token khusus &quot;Management API&quot;</p><p>NanoGPT menyediakan <strong>Management API token yang terpisah</strong> dari key biasa. Token ini <strong>tidak bisa menjalankan model atau menghabiskan saldo</strong> — fungsinya hanya untuk mengelola preset dan mengecek status langganan. Ini bonus keamanan yang bagus: kalau kamu butuh integrasi yang hanya membaca status, pakai token Management, bukan key utama.</p></div><div class="tip custom-block"><p class="custom-block-title">🎛️ Batasi key ke mode &quot;Subscription only&quot;</p><p>Ada kualitas-hidup dari komunitas yang berguna: key bisa dibatasi ke mode <strong>Subscription only</strong> lewat ikon ⚙️ (gear) di halaman <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">nano-gpt.com/api</a>. Dengan mode ini, key hanya bisa memakai model-langganan — berguna kalau kamu ingin membatasi penyalahgunaan key.</p></div><hr><h2 id="mengaktifkan-nanogpt-di-mikazuki-ai" tabindex="-1">Mengaktifkan NanoGPT di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-nanogpt-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan NanoGPT di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk NanoGPT:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>OpenAI Compatible</strong> (atau entri <strong>NanoGPT</strong>, bila ada di daftar provider).</li><li>Isi <strong>Base URL</strong>: <code>https://nano-gpt.com/api/v1</code></li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> dan <code>max_tokens</code> — lalu klik simpan.</li></ol><p>API NanoGPT berformat <em>OpenAI-compatible</em>, sehingga jalur <strong>OpenAI Compatible</strong> bekerja penuh di Mikazuki.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Client error pada output reasoning / thinking</p><p>Kalau client-mu error saat menerima output <em>reasoning/thinking</em> dari model tertentu, ada jalan keluar berikut ini: gunakan endpoint legacy di <code>https://nano-gpt.com/api/v1legacy</code> sebagai Base URL — format output-nya lebih kompatibel untuk client yang lebih tua. Detail di bagian <a href="#troubleshooting">Troubleshooting</a>.</p></div><hr><h2 id="bayar-deposit" tabindex="-1">Bayar &amp; Deposit <a class="header-anchor" href="#bayar-deposit" aria-label="Permalink to “Bayar &amp; Deposit”">​</a></h2><p>Sistem bayar NanoGPT adalah <strong>prepaid murni</strong>: kamu deposit dulu, lalu setiap request memotong saldo.</p><ul><li><strong>Deposit minimum sangat kecil</strong>: <strong>$0,10</strong> via crypto, atau <strong>$1</strong> via kartu (Stripe / Apple Pay / Google Pay) untuk deposit pertama.</li><li><strong>Tanpa fee deposit</strong> — semua deposit masuk penuh ke saldo.</li><li><strong>Saldo dalam USD</strong>.</li><li><strong>29 mata uang crypto</strong> didukung, termasuk <strong>Monero, BTC, Nano, USDC, USDT</strong>.</li><li>Deposit crypto mendapat <strong>bonus 3%</strong> — dan sekaligus jadi jalur pembayaran yang <strong>paling privat</strong> (tanpa identitas/akun).</li></ul><p>Detail metode pembayaran ada di <a href="https://nano-gpt.com/faq/payment-methods-and-cryptocurrencies" target="_blank" rel="noreferrer">FAQ pembayaran resmi NanoGPT</a>.</p><hr><h2 id="harga-langganan-opsional" tabindex="-1">Harga &amp; Langganan Opsional <a class="header-anchor" href="#harga-langganan-opsional" aria-label="Permalink to “Harga &amp; Langganan Opsional”">​</a></h2><ul><li>Harga mengikuti <strong>list price tanpa markup</strong> — kamu membayar apa yang dari provider harganya, tanpa selisih.</li><li><strong>Biaya exact dari setiap respons ditampilkan</strong> di halaman <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">Usage</a> — kamu bisa tahu persis berapa cent yang baru habis untuk request terakhir.</li><li><strong>Subscription bersifat opsional</strong>, bukan wajib: langganan bulanan (angkanya sekitar ±$12/bln — <em>ini per sumber pihak ketiga, cek situs resmi</em>) memberi akses ke model tertentu <strong>tanpa bayar per token</strong>.</li><li>Model berlabel <strong>beta/subscription</strong> hanya untuk pelanggan langganan; key mode <strong>&quot;Subscription only&quot;</strong> membatasi key-mu hanya ke model-langganan.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami sengaja tidak mencantumkan tabel harga per model di halaman ini — dengan 1.000+ model, angkanya cepat basi. Tinjau katalog dan harga di <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">nano-gpt.com/api</a> sebelum budgeting, dan monitor saldo-mu di halaman Usage.</p></div><hr><h2 id="privasi-data" tabindex="-1">Privasi &amp; Data <a class="header-anchor" href="#privasi-data" aria-label="Permalink to “Privasi &amp; Data”">​</a></h2><p>Ini bagian yang membuat NanoGPT berbeda — dan menarik bagi pengguna <em>roleplay</em> yang privasi-conscious:</p><ul><li><strong>&quot;History stays on your device&quot;</strong> — percakapan disimpan <strong>lokal di perangkat secara default</strong>, bukan di server. Tagline resminya: <em>&quot;Privacy First. No accounts required.&quot;</em></li><li><strong>Private Mode &amp; PII redaction</strong> (diluncurkan Mei 2026) — lapisan privasi tambahan untuk menyamarkan data pribadi.</li><li><strong>Batch API</strong> tersedia untuk pemakaian massal.</li><li>API-nya bisa diakses <strong>dari Tor</strong> menggunakan key biasa — tanpa perlakuan khusus apa pun.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Untuk pengguna privasi-conscious</p><p>Kalau kamu menganggap isi percakapan <em>roleplay</em>-mu sensitif, kombinasi di NanoGPT cukup langka: <strong>tanpa akun</strong> + <strong>pembayaran crypto (Monero)</strong> + <strong>riwayat lokal di peramban</strong> + <strong>akses dari Tor</strong>. Ini pengaturan privasi paling lengkap di antara semua provider di panduan ini.</p></div><hr><h2 id="model-katalog" tabindex="-1">Model &amp; Katalog <a class="header-anchor" href="#model-katalog" aria-label="Permalink to “Model &amp; Katalog”">​</a></h2><p>Katalog model lengkap bisa dijelajahi di <a href="https://nano-gpt.com/models" target="_blank" rel="noreferrer">halaman models NanoGPT</a> — teks, gambar, video, dan audio. Format ID model umumnya <strong><code>vendor/model</code></strong>; contoh formatnya <code>openai/gpt-6.1-sol</code>.</p><p>Panduan ini fokus ke <strong>chat completions</strong> karena itulah yang dipakai Mikazuki — endpoint lain (image, video, audio, embeddings) ada, tapi di luar cakupan panduan ini.</p><p>Selalu gunakan tombol 🔍 <strong>fetch models</strong> Mikazuki untuk mengambil nama model yang valid: dengan 1.000+ model dan format <code>vendor/model</code>, ketik manual sangat mudah salah.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Muncul 402 / &quot;live quote&quot; tanpa key</summary><p>Ini <strong>fitur, bukan error</strong>: NanoGPT punya mode <em>unauthenticated &quot;live quote&quot;</em> — request tanpa key bisa mengembalikan <strong>402 berisi quote harga</strong> yang bisa kamu bayar langsung dengan <strong>Nano atau Base USDC tanpa perlu membuat akun</strong>. Kalau kamu melihat 402 quote padahal belum memasang key, maksudnya NanoGPT sedang menawarkan harga persis untuk request tersebut. Untuk pemakaian di Mikazuki, tetap buat key normal agar alurnya sederhana.</p></details><details class="details custom-block"><summary>Client error pada output thinking / reasoning</summary><p>Beberapa model mengeluarkan <em>reasoning/thinking</em> yang format penulisannya bisa membuat client lebih tua padam. Solusinya: ganti <strong>Base URL</strong> ke endpoint legacy <code>https://nano-gpt.com/api/v1legacy</code> di pengaturan provider OpenAI Compatible-mu, lalu refetch models dan coba lagi.</p></details><details class="details custom-block"><summary>Saldo tidak cukup / request gagal</summary><p>Saldo prepaid-mu mungkin habis atau minimum deposit belum dilakukan. Cek saldo di halaman Usage <a href="https://nano-gpt.com/api" target="_blank" rel="noreferrer">nano-gpt.com/api</a>, lalu isi ulang — depositnya kecil ($0,10 crypto / $1 kartu) dan tanpa fee, jadi top-up kecil untuk mencoba tidak terasa berat. Ingat juga bonus 3% untuk jalur crypto.</p></details><details class="details custom-block"><summary>Jawaban terpotong</summary><p><code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil — model berhenti sebelum sempat menulis panjang. Naikkan nilainya, tapi ingat <code>max_tokens</code> ikut dipotong dari <code>context_window</code>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code> juga.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./deepseek.html">DeepSeek</a> — panduan padanan untuk provider top-up.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,42)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};